add_action( 'woocommerce_before_thankyou', 'perfectpixel_content_on_thank_you_page' );

function perfectpixel_content_on_thank_you_page( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order || $order->has_status( 'failed' ) ) {
		return;
	}
	echo '<div class="woocommerce-message perfectpixel-thankyou-message">' . wp_kses_post( '{{thankyou_message}}' ) . '</div>';
}
